using System;
using System.IO;
using System.Collections.Generic;
using CosmicBlock.UI;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
using TMPro;
using UnityEngine.EventSystems;
public static class Sprint1022SettingsVisualProbe {
 static double start;static int frames,count;static string errors="",warnings="";static readonly List<string> results=new List<string>();
 public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/Game.unity");start=EditorApplication.timeSinceStartup;Application.logMessageReceived+=Log;EditorApplication.update+=Check;EditorApplication.EnterPlaymode();}
 static void Check(){if(EditorApplication.timeSinceStartup-start>180){Finish(false,"timeout");return;}if(!EditorApplication.isPlaying||++frames<40)return;EditorApplication.update-=Check;try{var flow=UnityEngine.Object.FindAnyObjectByType<GameFlowController>();flow.ShowHome();flow.HomeRoot.transform.Find("BottomActions/SettingsButton").GetComponent<Button>().onClick.Invoke();Req(flow.HomeView.SettingsVisible,"actual settings button opens");foreach(int h in new[]{1920,2400,1440})Capture(h,flow);var close=flow.HomeRoot.transform.Find("SettingsPanel/Card/Close").GetComponent<Button>();close.onClick.Invoke();Req(!flow.HomeView.SettingsVisible&&flow.Screen==FlowScreen.Home,"close keeps HOME");for(int i=0;i<10;i++){flow.HomeView.ShowSettings();close.onClick.Invoke();}Req(!flow.HomeView.SettingsVisible,"repeated open/close safe");Finish(errors.Length==0,errors);}catch(Exception e){Finish(false,e.ToString());}}
 static void Capture(int h,GameFlowController flow){var canvas=GameObject.Find("GameCanvas").GetComponent<Canvas>();var safe=(RectTransform)canvas.transform.Find("SafeArea");var sa=safe.GetComponent<SafeArea>();var cam=Camera.main;var card=(RectTransform)flow.HomeRoot.transform.Find("SettingsPanel/Card");var settings=card.Find("AudioControls").GetComponent<AudioSettingsView>();var rt=new RenderTexture(1080,h,24);var mode=canvas.renderMode;var camera=canvas.worldCamera;var target=cam.targetTexture;var active=RenderTexture.active;bool enabled=sa.enabled,ortho=cam.orthographic;float size=cam.orthographicSize;var amin=safe.anchorMin;var amax=safe.anchorMax;var omin=safe.offsetMin;var omax=safe.offsetMax;Texture2D tex=null;
 try{sa.enabled=false;rt.Create();cam.targetTexture=rt;cam.orthographic=true;cam.orthographicSize=h/2f;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=cam;canvas.planeDistance=10;safe.anchorMin=h==2400?new Vector2(.02f,.04f):Vector2.zero;safe.anchorMax=h==2400?new Vector2(.98f,.94f):Vector2.one;safe.offsetMin=safe.offsetMax=Vector2.zero;Canvas.ForceUpdateCanvases();flow.HomeRoot.GetComponent<HomeFinalLayout>().Apply();card.GetComponent<SettingsPopupLayout>().Apply();Canvas.ForceUpdateCanvases();var bounds=World(safe);Req(Inside(bounds,World(card)),"settings safe bounds "+h);var dim=(RectTransform)card.parent.Find("DimOverlay");Req(Inside(World(dim),World((RectTransform)canvas.transform)),"full canvas dim "+h);
 foreach(var t in card.GetComponentsInChildren<TextMeshProUGUI>(true)){t.ForceMeshUpdate();bool body=t.name=="VolumeLabel"||t.name=="Haptic";float expected=(t.name=="TitleText"?26:body?18:21)*card.rect.width/440f;Req(!t.enableAutoSizing&&Mathf.Abs(t.fontSize-expected)<.01f,"common typography "+t.name);Req(t.font.name==(body?"CosmicPopupMedium":"CosmicPopupSemiBold")&&t.font.HasCharacters(t.text)&&!t.isTextOverflowing,"Korean glyph/font fit "+t.name);}
 foreach(var image in card.GetComponentsInChildren<Image>(true))Req(image.sprite==null&&image.color.a==0,"no PNG presentation in settings");Req(card.GetComponentsInChildren<Text>(true).Length==0,"all visible text TMP");Req(card.Find("CosmicFrame").GetComponent<HomeQuitMeshGraphic>().canvasRenderer.GetMesh().vertexCount>=253,"glow/depth actual mesh");var buttons=new[]{settings.BgmButton,settings.SfxButton,card.Find("Close").GetComponent<Button>()};foreach(var button in buttons){Req(button.targetGraphic is HomeQuitMeshGraphic,"mesh button target");Req(Inside(bounds,World((RectTransform)button.transform)),"button safe bounds");}Req(!World((RectTransform)buttons[0].transform).Overlaps(World((RectTransform)buttons[1].transform)),"rows do not overlap");
 var slider=settings.VolumeSlider;float value=slider.value;foreach(float v in new[]{0f,.5f,1f}){slider.SetValueWithoutNotify(v);Canvas.ForceUpdateCanvases();Req(Mathf.Abs(slider.fillRect.anchorMax.x-v)<.001f,"actual slider fill "+v);}slider.SetValueWithoutNotify(value);Req(Mathf.Abs(slider.handleRect.rect.width-slider.handleRect.rect.height)<.1f,"slider knob stays circular");Req(slider.fillRect.rect.height<((RectTransform)slider.transform).rect.height*.3f,"slider fill stays in thin track");Req(slider.targetGraphic is HomeQuitMeshGraphic&&Inside(bounds,World((RectTransform)slider.transform)),"slider knob and safe area");Canvas.ForceUpdateCanvases();cam.Render();var hits=new List<RaycastResult>();var play=(RectTransform)flow.HomeRoot.transform.Find("MainActions/GameStartButton");EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(cam,play.position)},hits);Req(hits.Count>0&&hits[0].gameObject.transform.IsChildOf(card.parent),"background HOME touch blocked");cam.Render();RenderTexture.active=rt;tex=new Texture2D(1080,h,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1080,h),0,0);tex.Apply();File.WriteAllBytes("Validation/settings_mesh_"+h+".png",tex.EncodeToPNG());results.Add("PASS settings render/font/buttons/slider/dim "+h);
 }finally{canvas.renderMode=mode;canvas.worldCamera=camera;cam.targetTexture=target;cam.orthographic=ortho;cam.orthographicSize=size;RenderTexture.active=active;safe.anchorMin=amin;safe.anchorMax=amax;safe.offsetMin=omin;safe.offsetMax=omax;sa.enabled=enabled;if(tex!=null)UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
 static Rect World(RectTransform r){var c=new Vector3[4];r.GetWorldCorners(c);return Rect.MinMaxRect(c[0].x,c[0].y,c[2].x,c[2].y);}static bool Inside(Rect a,Rect b)=>b.xMin>=a.xMin-.1f&&b.yMin>=a.yMin-.1f&&b.xMax<=a.xMax+.1f&&b.yMax<=a.yMax+.1f;
 static void Req(bool b,string m){count++;if(!b)throw new Exception(m);}static void Log(string m,string stack,LogType t){if(t==LogType.Warning)warnings+=m+"\n";if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)errors+=m+"\n";}
 static void Finish(bool pass,string why){EditorApplication.update-=Check;Application.logMessageReceived-=Log;File.WriteAllText("Validation/settings_mesh_tests.txt",string.Join("\n",results)+"\nAssertions="+count+"\nWarnings="+warnings+"\n"+(pass?"SETTINGS_MESH_PASS":why));EditorApplication.Exit(pass?0:1);}
}
